//! O1.6 — Opus decoding, measured against libopus.
//!
//! The spike (`docs/spikes/O1.2-audio-playback-and-opus.md` §2) set four gates
//! before an Opus decoder could ship. Three of them are enforced here:
//!
//! 1. **Differential.** Every committed Ogg Opus fixture is decoded through
//!    the product path (`validate_media` → `decode_to_canonical_pcm`) and
//!    compared sample-by-sample against a reference WAV produced by *libopus*,
//!    not by another pure-Rust implementation. The references live in
//!    `tests/fixtures/audio/reference/` and are regenerated by
//!    `scripts/make-audio-fixtures.sh` with
//!    `ffmpeg -c:a libopus -i <fixture>.opus -c:a pcm_s16le <name>.libopus.wav`
//!    — `-c:a libopus` *before* `-i` selects ffmpeg's libopus binding rather
//!    than its own native Opus decoder, so the reference is the reference
//!    implementation.
//! 2. **Signal.** The fixtures are 440 Hz (and 660 Hz on the right channel of
//!    the stereo one), so "no error" is not enough: the decoded tone is
//!    measured and must be the tone that was encoded.
//! 3. **Hostile input.** Truncated, forged and reserved-field Opus files fail
//!    closed with a typed [`AudioError`], never a panic and never silence
//!    presented as audio.
//!
//! The fourth gate — decoding a *real* `plaud_protocol::remux_to_ogg_opus`
//! output from a captured device `.ASR` — needs device hardware and remains
//! **unverified**; it is recorded as such in the spike note and the licence
//! register rather than implied here.

use std::path::{Path, PathBuf};

use plaudon_ai_contracts::job::JobContext;
use plaudon_audio::decode::{
    decode_to_canonical_pcm, CanonicalPcmProfile, ChannelPolicy, MemoryPcmSink, PcmSampleFormat,
};
use plaudon_audio::error::AudioError;
use plaudon_audio::validate::{validate_media, ValidationRequest};
use plaudon_domain::ids::JobId;

fn fixtures() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../tests/fixtures/audio")
        .canonicalize()
        .expect("the committed audio fixtures must exist")
}

fn valid(name: &str) -> PathBuf {
    fixtures().join("valid").join(name)
}

fn hostile(name: &str) -> PathBuf {
    fixtures().join("hostile").join(name)
}

/// Decode a fixture through the product path at its native 48 kHz, keeping
/// every channel, as 16-bit samples — the same shape as the reference WAV.
fn decode_native(path: &Path) -> Result<(Vec<i16>, u16), AudioError> {
    let media = validate_media(path, &ValidationRequest::default())?;
    let profile = CanonicalPcmProfile {
        sample_rate_hz: 48_000,
        channel_policy: ChannelPolicy::PreserveAll,
        sample_format: PcmSampleFormat::S16Le,
    };
    let mut sink = MemoryPcmSink::default();
    let outcome =
        decode_to_canonical_pcm(&media, &profile, &mut sink, &JobContext::new(JobId::new()))?;
    let samples = sink
        .bytes
        .as_chunks::<2>()
        .0
        .iter()
        .map(|pair| i16::from_le_bytes(*pair))
        .collect();
    Ok((samples, outcome.channels))
}

/// Read a 16-bit PCM WAV written by ffmpeg: parse the chunk list rather than
/// assuming a 44-byte header, because ffmpeg emits a `LIST` chunk too.
fn read_reference_wav(name: &str) -> (Vec<i16>, u16, u32) {
    let path = fixtures().join("reference").join(name);
    let bytes = std::fs::read(&path)
        .unwrap_or_else(|error| panic!("missing reference {}: {error}", path.display()));
    assert_eq!(&bytes[..4], b"RIFF", "{name} is not RIFF");
    assert_eq!(&bytes[8..12], b"WAVE", "{name} is not WAVE");

    let mut cursor = 12usize;
    let (mut channels, mut rate, mut data) = (0u16, 0u32, None);
    while cursor + 8 <= bytes.len() {
        let id = &bytes[cursor..cursor + 4];
        let size = u32::from_le_bytes([
            bytes[cursor + 4],
            bytes[cursor + 5],
            bytes[cursor + 6],
            bytes[cursor + 7],
        ]) as usize;
        let body = &bytes[cursor + 8..(cursor + 8 + size).min(bytes.len())];
        match id {
            b"fmt " => {
                channels = u16::from_le_bytes([body[2], body[3]]);
                rate = u32::from_le_bytes([body[4], body[5], body[6], body[7]]);
                assert_eq!(
                    u16::from_le_bytes([body[14], body[15]]),
                    16,
                    "{name} must be 16-bit"
                );
            }
            b"data" => data = Some(body),
            _ => {}
        }
        cursor += 8 + size + (size & 1);
    }

    let data = data.unwrap_or_else(|| panic!("{name} has no data chunk"));
    let samples = data
        .as_chunks::<2>()
        .0
        .iter()
        .map(|pair| i16::from_le_bytes(*pair))
        .collect();
    (samples, channels, rate)
}

/// Peak and RMS difference between two equal-length signals, in LSB.
fn difference(ours: &[i16], reference: &[i16]) -> (i32, f64) {
    let mut peak = 0i32;
    let mut squared = 0f64;
    for (a, b) in ours.iter().zip(reference) {
        let delta = i32::from(*a) - i32::from(*b);
        peak = peak.max(delta.abs());
        squared += f64::from(delta) * f64::from(delta);
    }
    (peak, (squared / ours.len().max(1) as f64).sqrt())
}

/// Dominant frequency of one channel, by counting zero crossings.
fn tone_hz(samples: &[i16], channels: usize, channel: usize, rate: u32) -> f64 {
    let frames: Vec<f64> = samples
        .iter()
        .skip(channel)
        .step_by(channels)
        .map(|sample| f64::from(*sample))
        .collect();
    // Skip the encoder's lead-in, where the tone has not settled.
    let start = (rate as usize / 20).min(frames.len() / 4);
    let window = &frames[start..];
    let mut crossings = 0usize;
    for pair in window.windows(2) {
        if (pair[0] < 0.0 && pair[1] >= 0.0) || (pair[0] >= 0.0 && pair[1] < 0.0) {
            crossings += 1;
        }
    }
    (crossings as f64 * f64::from(rate)) / (2.0 * window.len() as f64)
}

#[test]
fn every_opus_fixture_matches_the_libopus_reference() {
    // The shipped decoder works in 16-bit internally, exactly like the
    // reference's `pcm_s16le` output, so the two are directly comparable.
    // The only systematic difference is our canonical `f64 -> i16` step,
    // which scales by `i16::MAX` where the decoder scaled by 32768; that is
    // worth at most one LSB, and the bound below is deliberately tight enough
    // that a genuinely different decode could not hide under it.
    for (fixture, reference, channels) in [
        ("tone-mono-16k.opus", "tone-mono-16k.libopus.wav", 1u16),
        ("tone-mono-48k.opus", "tone-mono-48k.libopus.wav", 1),
        ("tone-mono-8k.opus", "tone-mono-8k.libopus.wav", 1),
        ("tone-stereo-48k.opus", "tone-stereo-48k.libopus.wav", 2),
    ] {
        let (ours, decoded_channels) =
            decode_native(&valid(fixture)).unwrap_or_else(|error| panic!("{fixture}: {error}"));
        let (reference_samples, reference_channels, reference_rate) = read_reference_wav(reference);

        assert_eq!(decoded_channels, channels, "{fixture} channel count");
        assert_eq!(reference_channels, channels, "{reference} channel count");
        assert_eq!(reference_rate, 48_000, "{reference} sample rate");
        assert_eq!(
            ours.len(),
            reference_samples.len(),
            "{fixture}: decoded {} samples, libopus produced {}",
            ours.len(),
            reference_samples.len()
        );

        let (peak, rms) = difference(&ours, &reference_samples);
        assert!(
            peak <= 2,
            "{fixture}: peak difference from libopus is {peak} LSB"
        );
        assert!(
            rms < 0.75,
            "{fixture}: RMS difference from libopus is {rms:.3} LSB"
        );
    }
}

#[test]
fn the_decoded_tone_is_the_tone_that_was_encoded() {
    for fixture in [
        "tone-mono-16k.opus",
        "tone-mono-48k.opus",
        "tone-mono-8k.opus",
    ] {
        let (samples, channels) = decode_native(&valid(fixture)).expect("decode");
        assert_eq!(channels, 1);
        let measured = tone_hz(&samples, 1, 0, 48_000);
        assert!(
            (measured - 440.0).abs() < 5.0,
            "{fixture}: measured {measured:.1} Hz, expected 440 Hz"
        );
        let peak = samples
            .iter()
            .map(|s| i32::from(*s).abs())
            .max()
            .unwrap_or(0);
        assert!(peak > 1_000, "{fixture}: decoded peak is only {peak}");
    }
}

#[test]
fn stereo_channels_are_decoded_separately_not_downmixed() {
    // 440 Hz on the left, 660 Hz on the right. A downmix or a channel copy
    // would make both measurements the same.
    let (samples, channels) = decode_native(&valid("tone-stereo-48k.opus")).expect("decode");
    assert_eq!(channels, 2);
    let left = tone_hz(&samples, 2, 0, 48_000);
    let right = tone_hz(&samples, 2, 1, 48_000);
    assert!((left - 440.0).abs() < 8.0, "left measured {left:.1} Hz");
    assert!((right - 660.0).abs() < 8.0, "right measured {right:.1} Hz");
}

#[test]
fn an_opus_file_validates_with_its_codec_named() {
    let media = validate_media(&valid("tone-mono-16k.opus"), &ValidationRequest::default())
        .expect("an Opus file must now validate");
    assert_eq!(
        media.profile().codec.get().map(String::as_str),
        Some("opus")
    );
    // Opus always decodes at 48 kHz; the rate in `OpusHead` describes the
    // original input and is not what comes out of the decoder.
    assert_eq!(media.profile().sample_rate_hz.get().copied(), Some(48_000));
    assert_eq!(media.profile().channels.get().copied(), Some(1));
    let duration = media.profile().duration_ms.get().copied().unwrap_or(0);
    assert!(
        (950..=1_050).contains(&duration),
        "duration was {duration} ms"
    );
}

#[test]
fn a_canonical_whisper_derivative_is_produced_from_opus() {
    // STT preprocessing asks for 16 kHz mono f32; the Opus path must satisfy
    // it like every other codec, and deterministically.
    let media = validate_media(&valid("tone-mono-16k.opus"), &ValidationRequest::default())
        .expect("validate");
    let profile = CanonicalPcmProfile::whisper_mono_16k();
    let mut first = MemoryPcmSink::default();
    let outcome =
        decode_to_canonical_pcm(&media, &profile, &mut first, &JobContext::new(JobId::new()))
            .expect("decode");
    assert_eq!(outcome.channels, 1);
    assert_eq!(outcome.sample_rate_hz, 16_000);
    assert!(
        (15_500..=16_500).contains(&outcome.frames),
        "frames: {}",
        outcome.frames
    );

    let mut second = MemoryPcmSink::default();
    let repeat = decode_to_canonical_pcm(
        &media,
        &profile,
        &mut second,
        &JobContext::new(JobId::new()),
    )
    .expect("decode");
    assert_eq!(outcome.digest, repeat.digest, "the decode must be stable");
    assert_eq!(first.bytes, second.bytes);
}

#[test]
fn hostile_opus_files_fail_closed_with_a_typed_error() {
    // Each of these is a real Ogg Opus file with exactly one thing wrong,
    // produced by `scripts/make-audio-fixtures.sh` with the page CRC
    // recomputed so the demuxer cannot reject it for the wrong reason.
    //
    // The first three are refused by the container layer: Symphonia's Ogg
    // reader will not build a mapper for a reserved channel mapping family or
    // a zero channel count, and a stream of headers has no audio pages, so it
    // reports a truncated stream rather than reaching the codec. The fourth
    // reaches our decoder, which refuses the packet.
    for (name, expected) in [
        ("opus-reserved-mapping.opus", "MEDIA_TRUNCATED"),
        ("opus-zero-channels.opus", "MEDIA_TRUNCATED"),
        ("opus-header-only.opus", "MEDIA_TRUNCATED"),
        ("opus-zero-frame-count.opus", "MEDIA_DECODE_FAILED"),
    ] {
        let outcome = validate_media(&hostile(name), &ValidationRequest::default())
            .and_then(|media| decode_native(media.path()).map(|_| ()));
        let Err(error) = outcome else {
            panic!("{name} must be refused, not decoded");
        };
        assert_eq!(error.code(), expected, "{name}: {error}");
    }
}

#[test]
fn a_truncated_opus_stream_yields_less_audio_and_never_claims_the_whole() {
    // A stream cut mid-page is indistinguishable from one that was stopped:
    // Ogg has no total-length field to contradict, so the honest outcome is
    // the audio that is actually there, never the duration the full file had,
    // and never a panic.
    let (whole, _) = decode_native(&valid("tone-mono-16k.opus")).expect("the intact fixture");
    let truncated = decode_native(&hostile("opus-truncated.opus"));
    match truncated {
        Ok((samples, channels)) => {
            assert_eq!(channels, 1);
            assert!(
                samples.len() < whole.len(),
                "a truncated stream decoded {} samples, as many as the whole file",
                samples.len()
            );
        }
        Err(error) => assert_eq!(error.code(), "MEDIA_TRUNCATED", "{error}"),
    }
}

#[test]
fn hostile_packets_are_typed_errors_rather_than_panics() {
    // The committed raw-packet corpus is the same one the fuzz target and the
    // stable corpus replay use; here it proves the *typed* half of the
    // contract, that nothing is accepted as audio by accident.
    let corpus = fixtures()
        .join("../fuzz-corpus/opus_packet")
        .canonicalize()
        .expect("the committed Opus packet corpus");
    let head = plaudon_audio::opus::OpusStreamParams::rtp(1).expect("mono stream");
    let mut decoder = plaudon_audio::opus::OpusPacketDecoder::new(head).expect("decoder");
    let mut entries: Vec<std::path::PathBuf> = std::fs::read_dir(&corpus)
        .expect("corpus")
        .map(|entry| entry.expect("entry").path())
        .filter(|path| path.is_file())
        .collect();
    entries.sort();
    assert!(entries.len() >= 15, "corpus shrank to {}", entries.len());

    let mut accepted = 0usize;
    for path in entries {
        let bytes = std::fs::read(&path).expect("corpus entry");
        match decoder.decode(&bytes) {
            Ok(pcm) => {
                accepted += 1;
                assert!(!pcm.is_empty(), "accepted a packet but produced no audio");
                assert!(
                    pcm.len() <= plaudon_audio::opus::MAX_FRAME_SAMPLES_PER_CHANNEL,
                    "{}: {} samples from one mono packet",
                    path.display(),
                    pcm.len()
                );
                assert!(
                    pcm.iter().all(|sample| sample.is_finite()),
                    "{}: produced a non-finite sample",
                    path.display()
                );
            }
            Err(error) => {
                // Every refusal is one of ours, with a stable detail string.
                assert!(!error.detail().is_empty(), "{}: {error}", path.display());
            }
        }
        decoder.reset();
    }
    assert!(
        accepted >= 3,
        "the corpus must still contain decodable packets, accepted {accepted}"
    );
}
